/// High-level RustO OCR Engine for multi-platform bindings.
final class RustO {
  RustO._(this._ffi, this._handle) {
    _finalizer.attach(this, _RustOFinalizerToken(_ffi._rustOFree, _handle), detach: this);
  }

  final RustoFfi _ffi;
  int _handle;
  bool _closed = false;

  static final Finalizer<_RustOFinalizerToken> _finalizer = Finalizer((token) {
    token.free(token.handle);
  });

  bool get isClosed => _closed;

  void close() {
    if (_closed) {
      return;
    }
    _closed = true;
    _finalizer.detach(this);
    _ffi._rustOFree(_handle);
  }

  void _ensureOpen() {
    if (_closed) {
      throw StateError('RustO is closed');
    }
  }

  /// Initializes an OCR engine instance with structured InitializeConfig.
  static RustO initialize(InitializeConfig config) {
    return _bindings().rustOCreateInitialize(config);
  }

  /// Initializes an OCR engine instance from a JSON configuration string.
  static RustO initializeFromJson(String configJson) {
    return _bindings().rustOCreateInitializeFromJson(configJson);
  }

  /// Runs text detection and recognition on an image source.
  DetectTextResult detectText(ImageSource source, OcrRunOptions options) {
    _ensureOpen();
    return _ffi.rustOInvokeDetectText(_handle, source, options);
  }

  /// Runs text detection and recognition on raw decoded interleaved 24-bit RGB pixel bytes.
  DetectTextResult detectTextRgb(Uint8List pixels, int width, int height, int stride, OcrRunOptions options) {
    _ensureOpen();
    return _ffi.rustOInvokeDetectTextRgb(_handle, pixels, width, height, stride, options);
  }

  /// Returns whether the engine is ready for inference.
  bool isReady() {
    _ensureOpen();
    return _ffi.rustOInvokeIsReady(_handle);
  }

  /// Returns the engine library version string.
  String version() {
    _ensureOpen();
    return _ffi.rustOInvokeVersion(_handle);
  }

}

